// Shared UI icons, calendar and persistent focus workspace. Keeps existing user data.
const iconPaths={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',subjects:'<path d="M12 5v16M3 3c4 0 7 0 9 2 2-2 5-2 9-2v16c-4 0-7 0-9 2-2-2-5-2-9-2Z"/>',tasks:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M9 4V2h6v2M8 11l2 2 5-5M8 17h8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h2m3 0h2m3 0h1"/>',focus:'<circle cx="12" cy="14" r="8"/><path d="M9 2h6m-3 0v4m0 4v4l3 2m4-10 2 2"/>',progress:'<path d="M3 3v18h18M7 15l4-5 4 3 6-8"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6ZM8 12l3 3 5-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',left:'<path d="m15 5-7 7 7 7"/>',right:'<path d="m9 5 7 7-7 7"/>',play:'<path d="m8 4 12 8-12 8Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>'};
function uiIcon(name){return `<svg class="icon-svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.subjects}</svg>`}
function refreshIcons(){
 document.querySelectorAll('.nav-item').forEach(n=>n.querySelector('.icon').innerHTML=uiIcon(n.dataset.page));
 document.querySelectorAll('.brand-mark').forEach(n=>n.innerHTML=uiIcon('bolt'));
 document.querySelectorAll('.level-shield').forEach(n=>n.innerHTML=uiIcon('shield'));
 document.querySelectorAll('.stat-icon').forEach((n,i)=>n.innerHTML=uiIcon(['progress','bolt','shield','focus'][i]));
 document.querySelectorAll('.timer-symbol').forEach(n=>n.innerHTML=uiIcon('focus'));
 document.querySelectorAll('.achievement-icon').forEach((n,i)=>n.innerHTML=uiIcon(['tasks','bolt','shield'][i]));
 document.querySelectorAll('[data-delete-subject],[data-delete-chapter]').forEach(n=>{n.innerHTML=uiIcon('close');n.setAttribute('aria-label','Supprimer')});
 document.querySelectorAll('.subject-symbol').forEach(n=>{if(['⚛','⚙'].includes(n.textContent))n.innerHTML=uiIcon('subjects')});
 document.querySelector('#menuBtn').innerHTML=uiIcon('menu');
}
pageNames.calendar='Calendrier';
let selectedDay=todayISO();
const originalRender=render;
render=function(){if(currentPage==='calendar')renderCalendar();else originalRender();refreshIcons()};
const originalOverview=renderOverview;
renderOverview=function(){originalOverview();const h=document.querySelector('.hero-row h1');h.textContent='Votre journée, bien organisée.';const v=document.querySelectorAll('.stat-value')[3];if(v)v.innerHTML=studyHours(todaySeconds())+'<small> étudiées</small>';refreshIcons()};

function calendarItems(date){return [...state.events.filter(e=>e.date===date).map(e=>({...e,kind:'event'})),...state.tasks.filter(t=>t.date===date).map(t=>({...t,kind:'task'}))].sort((a,b)=>(a.time||'').localeCompare(b.time||''))}
function renderCalendar(){
 const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7;
 const cells=Array.from({length:42},(_,i)=>{const d=new Date(y,m,i-offset+1),iso=localISO(d),items=calendarItems(iso);return `<button class="day-cell ${d.getMonth()!==m?'outside':''} ${iso===selectedDay?'selected':''} ${iso===todayISO()?'is-today':''}" data-day="${iso}" aria-label="${formatDate(d)}, ${items.length} éléments" aria-pressed="${iso===selectedDay}"><span class="day-number">${d.getDate()}</span>${items.slice(0,2).map(e=>`<span class="calendar-chip ${e.kind==='task'?'task':''}">${esc(e.time||'')} ${esc(e.title)}</span>`).join('')}${items.length>2?`<small>+${items.length-2}</small>`:''}</button>`}).join('');
 const items=calendarItems(selectedDay);
 document.querySelector('#page').innerHTML=header('Calendrier','Révisions, devoirs et rendez-vous : votre mois en un regard.',`<button class="primary-btn" data-new-event>+ Planifier</button>`)+`<div class="calendar-layout"><section class="card month-card"><div class="month-toolbar"><h2>${new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(first)}</h2><div><button class="secondary-btn" data-month="today">Aujourd’hui</button><button class="calendar-nav-btn" data-month="-1" aria-label="Mois précédent">${uiIcon('left')}</button><button class="calendar-nav-btn" data-month="1" aria-label="Mois suivant">${uiIcon('right')}</button></div></div><div class="month-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(s=>`<div class="weekday">${s}</div>`).join('')}${cells}</div><p class="helper">Sélectionnez un jour pour consulter ou modifier son programme.</p></section><aside class="card day-agenda"><span class="eyebrow">PROGRAMME DU JOUR</span><h2>${formatDate(new Date(selectedDay+'T12:00:00'))}</h2>${items.map(e=>`<div class="agenda-row"><strong>${esc(e.title)}</strong><small>${e.kind==='task'?'Tâche':'Événement'} · ${esc(e.time||'Toute la journée')}${e.end?' – '+esc(e.end):''}${e.done?' · Terminée':''}</small>${e.kind==='event'?`<div class="agenda-actions"><button class="secondary-btn" data-edit-event="${esc(e.id)}">Modifier</button><button class="icon-btn" data-remove-event="${esc(e.id)}" aria-label="Supprimer cet événement">${uiIcon('close')}</button></div>`:`<button class="link-btn" data-go="tasks">Voir les tâches</button>`}</div>`).join('')||'<p class="helper">Rien de prévu. Réservez un créneau pour avancer.</p>'}<button class="primary-btn" data-new-event>+ Ajouter un créneau</button></aside></div>`;
}
function eventEditor(id){const event=state.events.find(e=>e.id===id)||{date:selectedDay,time:'09:00',end:'10:00',title:''};openModal(id?'Modifier le créneau':'Planifier un créneau',field('Titre','title','text',`maxlength="140" value="${esc(event.title)}"`)+field('Date','date','date',`value="${esc(event.date)}"`)+`<div class="settings-grid">${field('Début','time','time',`value="${esc(event.time)}"`)}${field('Fin (facultative)','end','time',`value="${esc(event.end||'')}"`)}</div>`,d=>{if(id)Object.assign(event,d);else state.events.push({id:uid('e'),color:'#087f79',...d});selectedDay=d.date;calendarDate=new Date(d.date+'T12:00:00')});const form=document.querySelector('#modalForm'),end=form.elements.namedItem('end');end.required=false;const validate=()=>{const finish=form.elements.namedItem('end'),start=form.elements.namedItem('time');if(!finish||!start)return;finish.setCustomValidity(finish.value&&finish.value<=start.value?'La fin doit être après le début.':'')};form.addEventListener('input',validate);validate()}

state.focusSettings={work:25,break:5,goal:4,subject:'',...state.focusSettings};
let focusRun=state.focusRun||{mode:'work',duration:state.focusSettings.work*60,left:state.focusSettings.work*60,running:false,stamp:0,segments:{},subject:''};
function persistFocus(){state.focusRun=focusRun;save()}
function studyHours(seconds){const minutes=Math.floor(seconds/60);return `${Math.floor(minutes/60)} h ${String(minutes%60).padStart(2,'0')}`}
function todaySeconds(){return state.focusSessions.filter(s=>s.date===todayISO()).reduce((a,s)=>a+s.minutes*60,0)+(focusRun.mode==='work'?(focusRun.segments[todayISO()]||0):0)}
function addStudySpan(start,end){let cursor=start;while(cursor<end){const d=new Date(cursor),next=new Date(d.getFullYear(),d.getMonth(),d.getDate()+1).getTime(),stop=Math.min(next,end),key=localISO(d);focusRun.segments[key]=(focusRun.segments[key]||0)+(stop-cursor)/1000;cursor=stop}}
let lastFocusCheckpoint=0;
function settleFocus(now=Date.now()){if(!focusRun.running)return;const seconds=Math.min(focusRun.left,Math.max(0,(now-focusRun.stamp)/1000));if(focusRun.mode==='work')addStudySpan(focusRun.stamp,focusRun.stamp+seconds*1000);focusRun.left=Math.max(0,focusRun.left-seconds);focusRun.stamp=now;if(focusRun.left<=0)finishFocus();else if(now-lastFocusCheckpoint>=15000){lastFocusCheckpoint=now;persistFocus()}}
function finishFocus(){focusRun.running=false;let seconds=0;const group=uid('session');if(focusRun.mode==='work')for(const [date,value] of Object.entries(focusRun.segments)){if(value>0){state.focusSessions.push({id:uid('f'),group,date,minutes:value/60,subject:focusRun.subject});seconds+=value}}state.xp+=Math.floor(seconds/30);const mode=focusRun.mode;focusRun={mode,duration:state.focusSettings[mode]*60,left:state.focusSettings[mode]*60,running:false,stamp:0,segments:{},subject:''};persistFocus();showToast(mode==='work'?`Étude enregistrée · +${Math.floor(seconds/30)} XP`:'Pause terminée');if(currentPage==='focus')render()}
renderFocus=function(){
 const settings=state.focusSettings,locked=focusRun.running||focusRun.left<focusRun.duration;
 document.querySelector('#page').innerHTML=header('Votre espace de concentration','Choisissez votre rythme. Le reste peut attendre.')+`<div class="focus-layout"><section class="card focus-main"><div class="mode-switch" aria-label="Type de session"><button class="${focusRun.mode==='work'?'active':''}" data-focus-mode="work" ${locked?'disabled':''}>Étude</button><button class="${focusRun.mode==='break'?'active':''}" data-focus-mode="break" ${locked?'disabled':''}>Pause</button></div><div class="timer-ring" id="focusRing"><div><div class="timer-display" id="focusClock"></div><div class="timer-label">${focusRun.mode==='work'?'Temps de travail':'Temps de récupération'}</div></div></div><div class="timer-actions"><button class="primary-btn" data-focus-action="toggle">${uiIcon(focusRun.running?'pause':'play')} ${focusRun.running?'Mettre en pause':focusRun.left<focusRun.duration?'Reprendre':'Démarrer'}</button><button class="secondary-btn" data-focus-action="finish" ${!locked?'disabled':''}>Terminer & enregistrer</button></div><p class="helper">${focusRun.mode==='work'?'Les pauses ne comptent pas. Votre temps étudié est conservé même en terminant plus tôt.':'Prenez une vraie pause. Aucun temps d’étude ni XP ne sera ajouté.'}</p></section><div class="focus-side"><section class="card study-total"><span class="eyebrow">ÉTUDE AUJOURD’HUI</span><div class="hours-total" id="todayHours"></div><div class="progress-bar"><div class="progress-fill" id="dailyGoal"></div></div><p id="dailyCaption"></p></section><section class="card focus-settings"><h2>À votre rythme</h2><form id="focusSettings"><div class="settings-grid">${field('Étude (min)','work','number',`min="1" max="180" value="${settings.work}" ${locked?'disabled':''}`)}${field('Pause (min)','break','number',`min="1" max="60" value="${settings.break}" ${locked?'disabled':''}`)}</div><div class="field" style="margin-top:15px"><label for="focusSubject">Matière</label><select name="subject" id="focusSubject" ${locked?'disabled':''}>${subjectOptions()}</select></div>${field('Objectif quotidien (heures)','goal','number',`min="0.5" max="16" step="0.5" value="${settings.goal}"`)}<button class="secondary-btn" type="submit">Appliquer les réglages</button><p class="helper">${locked?'Terminez la session avant de modifier sa durée ou sa matière.':'Vos réglages sont synchronisés avec votre compte.'}</p></form></section></div></div><section class="card session-history"><h2>Vos sessions aujourd’hui</h2>${state.focusSessions.filter(s=>s.date===todayISO()).slice().reverse().map(s=>`<div class="session-row"><div>${esc(s.subject||'Étude libre')}<br><small>Session enregistrée</small></div><strong>${studyHours(s.minutes*60)}</strong></div>`).join('')||'<p class="helper">Votre première session apparaîtra ici.</p>'}</section>`;
 document.querySelector('#focusSubject').value=focusRun.subject||settings.subject;
 document.querySelector('#focusSettings').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));settings.goal=Number(d.goal);if(!locked){settings.work=Number(d.work);settings.break=Number(d.break);settings.subject=d.subject;focusRun.duration=settings[focusRun.mode]*60;focusRun.left=focusRun.duration}persistFocus();render();showToast('Réglages enregistrés')};updateFocusDisplay();
};
function updateFocusDisplay(){const clock=document.querySelector('#focusClock');if(!clock)return;clock.textContent=timeText(Math.ceil(focusRun.left));document.querySelector('#focusRing').style.setProperty('--timer-progress',`${100*(1-focusRun.left/focusRun.duration)}%`);document.querySelector('#todayHours').textContent=studyHours(todaySeconds());document.querySelector('#dailyGoal').style.width=Math.min(100,todaySeconds()/(state.focusSettings.goal*3600)*100)+'%';document.querySelector('#dailyCaption').textContent=`Objectif : ${state.focusSettings.goal} h · session en cours incluse`}
document.addEventListener('click',e=>{
 const month=e.target.closest('[data-month]');if(month){if(month.dataset.month==='today'){calendarDate=new Date();selectedDay=todayISO()}else{calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+Number(month.dataset.month),1)}render()}
 const day=e.target.closest('[data-day]');if(day){selectedDay=day.dataset.day;render()}
 if(e.target.closest('[data-new-event]'))eventEditor();
 const edit=e.target.closest('[data-edit-event]');if(edit)eventEditor(edit.dataset.editEvent);
 const remove=e.target.closest('[data-remove-event]');if(remove&&confirm('Supprimer cet événement ?')){state.events=state.events.filter(x=>x.id!==remove.dataset.removeEvent);save();render()}
 const mode=e.target.closest('[data-focus-mode]');if(mode&&!mode.disabled){focusRun.mode=mode.dataset.focusMode;focusRun.duration=state.focusSettings[focusRun.mode]*60;focusRun.left=focusRun.duration;persistFocus();render()}
 const action=e.target.closest('[data-focus-action]');if(action&&!action.disabled){settleFocus();if(action.dataset.focusAction==='finish'){finishFocus()}else{focusRun.running=!focusRun.running;focusRun.stamp=Date.now();if(!focusRun.subject)focusRun.subject=state.focusSettings.subject;persistFocus();render()}}
});
// Timestamp-based accounting keeps time accurate when the browser throttles background tabs.
// Resume only after the authenticated account state has been loaded.
setInterval(()=>{settleFocus();updateFocusDisplay()},1000);
window.addEventListener('pagehide',()=>{settleFocus();persistFocus()});
render();
